// ============================================================================
// ---- EDIT FROM HERE ---------------------------------------------------------
const transforms = [
  // Run first, in order. Change item.data in place.
  // (item) => { item.data.email = item.data.email.replace(/\+[^@]*@/, '@'); },
];
const rules = [
  // Return a sentence to REJECT the record, or nothing to accept it.
  // (item) => (item.data.amount > 10000 ? 'amount over 10000 needs manual approval' : null),
];
const payload = (item, ctx) => item.data;     // what is SENT to the destination (default: the cleaned record)
