const C = $('CONFIG').first().json;
const P = $input.first().json;
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const headers = JSON.parse(C.SERVICE_HEADERS_JSON || '{}');
const base = (u) => String(u).replace(/\/+$/, '');
const call = async (method, url, body, extraHeaders, timeout) => {
  try {
    const r = await this.helpers.httpRequest({ method, url, body, json: true, headers: { ...headers, ...(extraHeaders || {}) }, timeout, returnFullResponse: true, ignoreHttpStatusErrors: true });
    return { status: r.statusCode, body: r.body };
  } catch (e) { return { status: null, error: String((e && e.message) || e).slice(0, 160) }; }
};
const started = Date.now();
const RM = $('Claim Dead Letters').isExecuted ? $('Claim Dead Letters').first().json.replay.map : null;
const budgetMs = Number(C.MAX_LOAD_SECONDS) * 1000;
const results = P.failed.map((f) => ({ row: f.row, record_id: f.record_id, status: f.status, failure_type: f.failure_type, reasons: f.reasons, raw: f.record }));
const breaker = { tripped: false, open_at_start: false, status_check: C.BREAKER_API_URL ? 'ok' : 'not_configured', failures_reported: 0 };

const externalOpen = async () => {
  if (!C.BREAKER_API_URL) return false;
  const r = await call('GET', base(C.BREAKER_API_URL) + '/status', undefined, {}, Number(C.REQUEST_TIMEOUT_MS));
  if (r.status === 200 && r.body && typeof r.body.open === 'boolean') { breaker.status_check = 'ok'; return r.body.open; }
  breaker.status_check = 'unreachable';        // the breaker lookup is advisory: if it cannot be read we carry on (fail open)
  return false;
};
let skipReason = null;
if (await externalOpen()) { skipReason = 'circuit breaker is open: the destination was reported unhealthy, so nothing was sent'; breaker.open_at_start = true; }
let consecutive = 0;
const isTransient = (r) => r.status === null || r.status >= 500 || r.status === 408 || r.status === 429;

const conc = Math.max(1, Math.min(10, Number(C.LOAD_CONCURRENCY) || 1));
const loadOne = async (item) => {   // loads ONE record; up to LOAD_CONCURRENCY of these run at the same time
  const base_r = { row: item.row, record_id: item.record_id, raw: item.record };
  if (!skipReason && Date.now() - started > budgetMs) skipReason = `batch time budget of ${C.MAX_LOAD_SECONDS}s used up; the rest were not attempted`;
