  let r, attempts = 0;
  const idem = RM && RM[item.row] ? RM[item.row].idem : `${P.batch_id}:${item.record_id}`;   // a replayed record keeps the key of its ORIGINAL batch, so a record that actually reached the destination is never stored twice
  while (true) {
    attempts++;
    r = await call('POST', base(C.DESTINATION_API_URL) + '/records', item.payload, { 'idempotency-key': idem }, Number(C.LOAD_TIMEOUT_MS));
    if (r.status !== null && r.status >= 200 && r.status < 300) break;
    if (!isTransient(r) || attempts >= Number(C.LOAD_MAX_ATTEMPTS)) break;
    if (Date.now() - started > budgetMs) break;
    await sleep(Number(C.LOAD_RETRY_BACKOFF_MS) * Math.pow(2, attempts - 1));
  }
  const ok = r.status !== null && r.status >= 200 && r.status < 300;
  if (ok) { consecutive = 0; results.push({ ...base_r, status: 'loaded', reasons: [], attempts }); return; }
  const why = r.status === null ? 'no response' : 'HTTP ' + r.status;
  if (!isTransient(r)) {
