    results.push({ ...base_r, status: 'rejected', failure_type: 'destination_rejected', reasons: [`the destination rejected the record (${why})`], attempts });
    return;
  }
  consecutive++;
  results.push({ ...base_r, status: 'load_failed', failure_type: 'load', reasons: [`the destination failed after ${attempts} attempt${attempts === 1 ? '' : 's'} (${why})`], attempts });
