const worker = async () => { while (next < P.valid.length) { const item = P.valid[next++]; await loadOne(item); } };
await Promise.all(Array.from({ length: Math.min(conc, P.valid.length) }, worker));
results.sort((a, b) => a.row - b.row);
return [{ json: { batch_id: P.batch_id, source: P.source, total: P.total, results, breaker, budget_exceeded: Date.now() - started > budgetMs } }];

const D = $input.first().json;
const items = D.results.filter((r) => r.status !== 'loaded').map((r) => ({ row: r.row, record_id: r.record_id, status: r.status, failure_type: r.failure_type, reasons: r.reasons, record: r.raw }));
const replay = $('Claim Dead Letters').isExecuted;   // a replay updates the EXISTING dead letters; it never files new ones
return [{ json: { ...D, dl_items: items, has_dl: !replay && items.length > 0 } }];

const esc = (s) => String(s === undefined || s === null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const C = $('CONFIG').first().json;
const D = $('Dead Letter Items').first().json;
const r = $input.first().json;
const RP = $('Claim Dead Letters').isExecuted ? { R: $('Claim Dead Letters').first().json.replay, S: $('Settle Replay').first().json.replay_settle } : null;
let dl = 'not_needed';
if (D.has_dl) {
  if (!C.DEAD_LETTER_API_URL) dl = 'not_configured';
  else dl = (typeof r.statusCode === 'number' && r.statusCode >= 200 && r.statusCode < 300) ? 'saved' : 'failed';
}
const counts = { total: D.total, loaded: 0, invalid: 0, rejected: 0, load_failed: 0, skipped: 0 };
for (const x of D.results) counts[x.status]++;
const status = counts.loaded === counts.total ? 'completed' : counts.loaded > 0 ? 'partial' : 'failed';
const notes = [];
const id = D.batch_id;
if (counts.load_failed > 0 || counts.skipped > 0) notes.push({ text: `Batch ${id} had operational failures: ${counts.load_failed} load_failed, ${counts.skipped} skipped (of ${counts.total} total)${D.breaker.tripped || D.breaker.open_at_start ? '; the circuit breaker stopped the load' : ''}${D.budget_exceeded ? '; the time budget ran out' : ''}.` });
if (RP) {
  const S = RP.S;
  notes.push({ text: `Replay ${id}: ${D.total} record(s) were re-run from the dead-letter store: ${counts.loaded} loaded, ${D.total - counts.loaded} still not loaded.` });
  if (S.resolve_failed.length) notes.push({ text: `Replay ${id}: ${S.resolve_failed.length} record(s) could NOT be updated in the dead-letter store (${S.resolve_failed.join(', ')}). They will show up as open again; the destination de-duplicates on the idempotency key, so replaying them again is harmless.` });
}
if (dl === 'failed') notes.push({ text: `Batch ${id}: ${D.dl_items.length} record(s) could NOT be saved to the dead-letter store. They are only in the response to the caller.` });
return [{ json: { http_status: 200,
